<div class="stack"><div><h1>Audit log</h1><p class="muted">Traccia azioni amministrative rilevanti. Totale: <?php echo (int) ($total ?? count($items)); ?> voci.</p></div><div class="table-wrap"><table class="table"><thead><tr><th>Azione</th><th>Attore</th><th>Tipo entità</th><th>ID entità</th><th>Data</th></tr></thead><tbody><?php foreach ($items as $item): ?><tr><td><?php echo e($item['action'] ?? '-'); ?></td><td><?php echo e($item['actor'] ?? $item['username'] ?? '-'); ?></td><td><?php echo e((string) ($item['entity_type'] ?? '-')); ?></td><td><?php echo e((string) ($item['entity_id'] ?? $item['target'] ?? '-')); ?></td><td><?php echo e($item['created_at'] ?? '-'); ?></td></tr><?php endforeach; ?></tbody></table></div><?php if (($pages ?? 1) > 1): ?><div class="pagination"><?php for ($p = 1; $p <= $pages; $p++): ?><a class="page-link <?php echo $p === ($page ?? 1) ? 'is-active' : ''; ?>" href="?page=<?php echo $p; ?>"><?php echo $p; ?></a><?php endfor; ?></div><?php endif; ?></div>
